 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var selectedConfigId = [];
    selectedConfigId[0] = (event.payload && event.payload.appliedFilters && event.payload.appliedFilters[0] && event.payload.appliedFilters[0].values && event.payload.appliedFilters[0].values[0]) || '';
    return {
        propName: "selectedSsaId",
        value: selectedConfigId
    };
}

